            st.mode = MODE_EXPLORE;
            Character wea;
            wea.name = "Wea";
            wea.classIndex = 0; wea.level = 1;
            wea.race = 0;
            wea.hp = 30; wea.maxHp = 30;
            wea.abilities.str = 3;
            wea.armor.id = items::ARMOR_NONE_EQUIPPED;
