            pt.push_back(a);
            std::vector<ai::Actor> mons;
            ai::Actor m;
            m.team = 1; m.hitDice = 1;
            m.hp = 6; m.maxHp = 6;
            mons.push_back(m);
            ai::Encounter enc(pt, mons, 7);
            enc.setWaterFight();
            enc.setOpeningBands(1);
            enc.stepRound();
            bool turned = false;
            for (const auto& ln : enc.log())
                if (ln.text.find(
                        "the water turns the stroke")
                    != std::string::npos) turned = true;
            if (!turned) ++bad;
            if (enc.monsters()[0].hp != 6) ++bad;
